from parser.bounds import parse_index

def test_bounds_trigger():
    items = ['a', 'b', 'c']
    # The goal is to trigger an IndexError
    # We use a known out-of-bounds index
    try:
        parse_index(items, 10)
    except IndexError:
        print("Triggered successfully")
        return True
    return False

if __name__ == "__main__":
    if test_bounds_trigger():
        print("SUCCESS")
    else:
        print("FAILURE")
        exit(1)
